using System;
using Autodesk.Revit.DB;
using System.Linq;

// AuroraRevit v1.8.3 educational template: Create a Sheet Index
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_Sheets);
    var schedule = ViewSchedule.CreateSchedule(doc, category);
    schedule.Name = "SHEET INDEX";
}

using System;
using Autodesk.Revit.DB;
using System.Linq;

// AuroraRevit v1.8.3 educational template: Read Project Information
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_ProjectInformation);
    var info = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_ProjectInformation).WhereElementIsNotElementType().FirstOrDefault();
    var projectName = info?.LookupParameter("Project Name")?.AsString();
}

using System;
