using System.Linq;

// AuroraRevit v1.8.3 educational template: Find Unplaced Views on Sheets
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_Views);
    var views = new FilteredElementCollector(doc).OfClass(typeof(View)).Cast<View>().Where(x => !x.IsTemplate && x.ViewType != ViewType.Schedule).ToList();
}

