// AuroraRevit v1.8.3 educational template: Find Elements with Empty Mark
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_GenericModel);
    var elements = new FilteredElementCollector(doc).WhereElementIsNotElementType().ToElements();
    var unmarked = elements.Where(x => string.IsNullOrWhiteSpace(x.LookupParameter("Mark")?.AsString())).ToList();
}

